import { readFileSync, readdirSync, writeFileSync } from 'node:fs';
const dir = 'findings';
const all = [];
for (const f of readdirSync(dir).sort()) {
  if (!f.endsWith('.json')) continue;
  const dept = f.replace('.json','');
  const arr = JSON.parse(readFileSync(dir+'/'+f, 'utf8'));
  for (const finding of arr) all.push({dept, ...finding});
}
const DROP_IDS = new Set([
  'access-login-no-rate-limit',
  'access-session-cookie-flags-missing',
  'platform-http-only-no-tls',
  'data-006',
  'platform-hardcoded-cookie-secret',
]);
const kept = all.filter(f => !DROP_IDS.has(f.id));
console.log('kept count', kept.length);
const counts = {};
for (const f of kept) counts[f.severity] = (counts[f.severity]||0)+1;
console.log(counts);
// verify dedup key uniqueness
const seen = new Set();
for (const f of kept) {
  const k = `${f.file}:${f.line}:${f.cwe}`;
  if (seen.has(k)) console.log('DUP STILL PRESENT', k, f.id);
  seen.add(k);
}
// strip dept field, write findings.json preserving field order from original (dept was appended, remove it)
const out = kept.map(({dept, ...rest}) => rest);
writeFileSync('/tmp/findings.union.json', JSON.stringify(out, null, 2) + '\n');
EOF
node /tmp/build_union.mjs","description":"Build deduplicated union and severity counts"}

